import json

class Event:
    def __init__(self, detail_type: str, source: str, detail: dict):
        self.detail_type = detail_type
        self.source = source
        self.detail = detail

    def to_json(self):
        return json.dumps({
            "detail-type": self.detail_type,
            "source": self.source,
            "detail": self.detail
        })

import os
from messaging_client import MessagingClient
from messaging_models import Event

def publish_event(topic_arn: str, event: Event):
    client = MessagingClient()
    sns_client = client.get_sns_client()

    try:
        response = sns_client.publish(
            TopicArn=topic_arn,
            Message=event.to_json(),
            MessageAttributes={
                'detail-type': {
                    'DataType': 'String',
                    'StringValue': event.detail_type
                },
                'source': {
                    'DataType': 'String',
                    'StringValue': event.source
                }
            }
        )
        print(f"Event published successfully: {response['MessageId']}")
        return response
    except Exception as e:
        print(f"Error publishing event: {e}")
        raise

if __name__ == '__main__':
